mapper.select:
WHERE U.USE_YN != 'N' AND U.AUTHRT_CD = #{authrtCd} AND U.USER_STTS_CD = #{userSttsCd}
AND (U.USER_ID LIKE CONCAT('%', #{searchKeyword}, '%') OR U.USER_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR U.OGDP_BZENTY_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR U.DEPT_NM LIKE CONCAT('%', #{searchKeyword}, '%'))
ORDER BY U.REG_DT DESC, U.USER_ID
